/* @socom-skeleton stub MapToGameLevel__FPCc */
int MapToGameLevel(const char *map)
{
	/* 0x32f980: "mp1".."mp10" -> 1..10, else 0 */
	if (map == NULL)
		return 0;
	static const char *const maps[] = { "mp1", "mp2", "mp3", "mp4", "mp5", "mp6", "mp7", "mp8", "mp9", "mp10" };
	for (int i = 0; i < 10; i++)
	{
		if (strcmp(map, maps[i]) == 0)
			return i + 1;
	}
	return 0;
}

