	/* 0x32a330: the clan's leadership given to the named member (MP_PLAYER_NOT_FOUND when there is
	 * no such member) */
	ClanMemberItem *member = (name != NULL && name[0] != '\0') ? LobbyFindMember(name) : NULL;
