	/* 0x326f00: waits for the connect thread (a second at a time), disconnects from Medius, closes
	 * DME, and closes the lobby (returns 1 in the ELF when open; no caller reads it) */
	if (!m_isopen)
		return;
	while (ThreadId != 0)
		zSysSleep(zSys.timerTicksPerSecond);
